SourceCode.Declaration:
/// <summary>
/// What <c>MXTXppInterpreterExecutor::execute</c> did with a script: the parse errors when it didn't run it, or the value
/// of the return statement that ended it. An exception of the script leaves execute as before, so it isn't here.
/// </summary>
internal final class MXTXppInterpreterExecutionResult
{
    XppInterpreter.Parser.ParseResult parseResult;
    System.Object returnValue;
}

Method.Source:
public static MXTXppInterpreterExecutionResult construct(XppInterpreter.Parser.ParseResult _parseResult)
{
    MXTXppInterpreterExecutionResult result = new MXTXppInterpreterExecutionResult();

    result.parmParseResult(_parseResult);

    return result;
}

public XppInterpreter.Parser.ParseResult parmParseResult(XppInterpreter.Parser.ParseResult _parseResult = parseResult)
{
    parseResult = _parseResult;

    return parseResult;
}

/// <summary>
/// The value of the return statement that ended the script, or null
/// </summary>
public System.Object parmReturnValue(System.Object _returnValue = returnValue)
{
    returnValue = _returnValue;

    return returnValue;
}

/// <summary>
/// The script parsed, so execute ran it to its end
/// </summary>
public boolean hasRun()
{
    return parseResult != null && parseResult.IsCorrect;
}

/// <summary>
/// The errors that kept the script from running, as "Line n, position m: message"
/// </summary>
public List parseErrors()
{
    return MXTXppCoreScript::parseErrorList(parseResult);
}

/// <summary>
/// The return value as text: an X++ value as strFmt shows it, a container as [a, b], an object by its ToString
/// </summary>
public str returnValueText()
{
    return returnValue == null ? '' : MXTXppInterpreterExecutionResult::valueText(returnValue);
}

private static str valueText(anytype _value)
{
    switch (typeOf(_value))
    {
        // con2Str shows only the first value of a container inside a container
        case Types::Container:
            container values = _value;
            str text;

            for (int i = 1; i <= conLen(values); i++)
            {
                text += (i > 1 ? ', ' : '') + MXTXppInterpreterExecutionResult::valueText(conPeek(values, i));
            }

            return '[' + text + ']';

        case Types::Class:
            System.Object instance = _value;
            return instance == null ? '' : instance.ToString();

        default:
            return strFmt('%1', _value);
    }
}
